import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import 'database_helper.dart';
import 'diary_entry.dart';
import 'work_page.dart';

class HistoryPage extends StatefulWidget { final String initialFilter; const HistoryPage({super.key,this.initialFilter='All'}); @override State<HistoryPage> createState()=>_HistoryPageState(); }
class _HistoryPageState extends State<HistoryPage>{
 late Future<List<DiaryEntry>> entriesFuture; final searchController=TextEditingController(); String searchText=''; late String selectedFilter;
 @override void initState(){super.initState();selectedFilter=widget.initialFilter;refreshEntries();} void refreshEntries(){entriesFuture=DatabaseHelper.instance.getAllEntries();}
 DateTime? _parseDate(String v){final p=v.split('-');if(p.length!=3)return null;return DateTime.tryParse('${p[2]}-${p[1]}-${p[0]}');} DateTime _startOfWeek(DateTime d){final x=DateTime(d.year,d.month,d.day);return x.subtract(Duration(days:x.weekday-1));} DateTime _endOfWeek(DateTime d)=>_startOfWeek(d).add(const Duration(days:6)); String _dateLabel(DateTime d)=>DateFormat('d MMM').format(d); String _weekLabel(DateTime d)=>'${_dateLabel(d)}–${_dateLabel(_endOfWeek(d))}'; String _monthLabel(DateTime d)=>DateFormat('MMMM yyyy').format(d);
 List<DateTime> _weeksForLastFourMonths(){final n=DateTime.now();final c=DateTime(n.year,n.month-3,1);var x=_startOfWeek(n);final r=<DateTime>[];while(!x.isBefore(c)){r.add(x);x=x.subtract(const Duration(days:7));}return r;} List<DateTime> _recentMonths(int c){final n=DateTime.now();return List.generate(c,(i)=>DateTime(n.year,n.month-i,1));}
 Future<void> _showWeeklyHistory()async{final weeks=_weeksForLastFourMonths();await showModalBottomSheet<void>(context:context,isScrollControlled:true,showDragHandle:true,builder:(sc){final s=Theme.of(sc).colorScheme;return SafeArea(child:SizedBox(height:MediaQuery.of(sc).size.height*.78,child:Column(children:[const Padding(padding:EdgeInsets.fromLTRB(20,4,20,12),child:Text('Weekly History',style:TextStyle(fontSize:20,fontWeight:FontWeight.w800))),Expanded(child:ListView.builder(itemCount:weeks.length,itemBuilder:(c,i){final w=weeks[i];return ListTile(leading:Icon(Icons.calendar_view_week,color:s.primary,size:20),title:Text(i==0?'This Week':'$i Week',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(_weekLabel(w)),trailing:const Icon(Icons.chevron_right),onTap:(){Navigator.pop(sc);setState(()=>selectedFilter='Week:${w.toIso8601String()}');});}))])));});}
 Future<void> _showMonthlyHistory()async{final months=_recentMonths(12);await showModalBottomSheet<void>(context:context,isScrollControlled:true,showDragHandle:true,builder:(sc){final s=Theme.of(sc).colorScheme;return SafeArea(child:SizedBox(height:MediaQuery.of(sc).size.height*.78,child:Column(children:[const Padding(padding:EdgeInsets.fromLTRB(20,4,20,12),child:Text('Monthly History',style:TextStyle(fontSize:20,fontWeight:FontWeight.w800))),Expanded(child:ListView.builder(itemCount:months.length,itemBuilder:(c,i){final m=months[i];return ListTile(leading:Icon(Icons.calendar_month,color:s.primary,size:20),title:Text(i==0?'This Month':'$i Month',style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(_monthLabel(m)),trailing:const Icon(Icons.chevron_right),onTap:(){Navigator.pop(sc);setState(()=>selectedFilter='Month:${m.year}-${m.month.toString().padLeft(2,'0')}');});}))])));});}
 Future<void> _searchByMonth()async{final n=DateTime.now();final p=await showDatePicker(context:context,initialDate:n,firstDate:DateTime(2000),lastDate:DateTime(n.year+1,12,31),helpText:'Select any date in the month',fieldLabelText:'Month');if(p==null||!mounted)return;setState(()=>selectedFilter='Month:${p.year}-${p.month.toString().padLeft(2,'0')}');}
 Future<void> deleteEntry(int id)async{await DatabaseHelper.instance.deleteEntry(id);setState(refreshEntries);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Entry Deleted Successfully')));}
 Future<void> confirmDelete(DiaryEntry entry)async{final confirm=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Delete Entry'),content:Text('Delete "${entry.itemName}" ?'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Delete'))]));if(confirm==true)await deleteEntry(entry.id!);}
 Widget icon3D(BuildContext context,IconData icon,{double size=26, Color? color}){final s=Theme.of(context).colorScheme;final base=color??s.primary;final deep=Color.alphaBlend(Colors.black.withValues(alpha:.20),base);return SizedBox(width:size+8,height:size+8,child:Stack(alignment:Alignment.center,children:[Transform.translate(offset:const Offset(1.2,1.5),child:Icon(icon,size:size,color:Colors.black.withValues(alpha:.20))),ShaderMask(blendMode:BlendMode.srcIn,shaderCallback:(bounds)=>LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[Colors.white,base,deep]).createShader(bounds),child:Icon(icon,size:size)),Transform.translate(offset:const Offset(-.8,-.8),child:Icon(icon,size:size*.52,color:Colors.white.withValues(alpha:.32)))]));}
 @override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:const Text('History')),body:FutureBuilder<List<DiaryEntry>>(future:entriesFuture,builder:(context,snapshot){if(snapshot.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(snapshot.hasError)return Center(child:Text('Error: ${snapshot.error}'));final entries=snapshot.data??[];final filtered=entries.where((entry){final q=searchText.toLowerCase();if(!entry.itemName.toLowerCase().contains(q)&&!entry.workDate.toLowerCase().contains(q))return false;final d=_parseDate(entry.workDate);if(d==null)return false;final x=DateTime(d.year,d.month,d.day);if(selectedFilter=='Today'){final n=DateTime.now();return x==DateTime(n.year,n.month,n.day);}if(selectedFilter.startsWith('Week:')){final w=DateTime.tryParse(selectedFilter.substring(5));if(w==null)return false;return !x.isBefore(_startOfWeek(w))&&!x.isAfter(_endOfWeek(w));}if(selectedFilter.startsWith('Month:')){final p=selectedFilter.substring(6).split('-');final y=int.tryParse(p[0]),m=int.tryParse(p[1]);return y!=null&&m!=null&&d.year==y&&d.month==m;}return true;}).toList();final totalPieces=filtered.fold<int>(0,(sum,e)=>sum+e.pieces),totalEarnings=filtered.fold<double>(0,(sum,e)=>sum+e.total);return Column(children:[Padding(padding:const EdgeInsets.all(8),child:TextField(controller:searchController,decoration:const InputDecoration(hintText:'Search Item or Date...',prefixIcon:Icon(Icons.search),border:OutlineInputBorder()),onChanged:(v)=>setState(()=>searchText=v))),Padding(padding:const EdgeInsets.fromLTRB(8,8,8,0),child:Row(children:[Expanded(child:OutlinedButton.icon(onPressed:_showWeeklyHistory,icon:icon3D(context,Icons.calendar_view_week,size:18,color:Colors.blue),label:const Text('Weekly History'))),const SizedBox(width:8),Expanded(child:OutlinedButton.icon(onPressed:_showMonthlyHistory,icon:icon3D(context,Icons.calendar_month,size:18,color:Colors.orange),label:const Text('Monthly History')))])),if(selectedFilter.startsWith('Week:')||selectedFilter.startsWith('Month:'))Padding(padding:const EdgeInsets.fromLTRB(12,8,12,0),child:Row(children:[Expanded(child:Text(selectedFilter.startsWith('Week:')?'Selected Week: ${_weekLabel(DateTime.parse(selectedFilter.substring(5)))}':'Selected Month: ${_monthLabel(DateTime.parse('${selectedFilter.substring(6)}-01'))}',style:const TextStyle(fontWeight:FontWeight.w700))),TextButton(onPressed:()=>setState(()=>selectedFilter='All'),child:const Text('Clear'))])),const SizedBox(height:8),Card(margin:const EdgeInsets.all(8),child:Padding(padding:const EdgeInsets.all(12),child:Row(mainAxisAlignment:MainAxisAlignment.spaceAround,children:[Column(children:[const Text('Entries',style:TextStyle(fontWeight:FontWeight.bold)),Text(filtered.length.toString())]),Column(children:[const Text('Pieces',style:TextStyle(fontWeight:FontWeight.bold)),Text(totalPieces.toString())]),Column(children:[const Text('Earnings',style:TextStyle(fontWeight:FontWeight.bold)),Text('Rs ${totalEarnings.toStringAsFixed(0)}')])]))),const SizedBox(height:8),Expanded(child:filtered.isEmpty?const Center(child:Text('No Entries Yet')):ListView.builder(itemCount:filtered.length,itemBuilder:(context,index){final entry=filtered[index],date=_parseDate(entry.workDate);final dayName=date==null?'':DateFormat('EEEE').format(date);return Card(elevation:4,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(16)),margin:const EdgeInsets.symmetric(horizontal:8,vertical:6),child:Padding(padding:const EdgeInsets.all(8),child:ListTile(contentPadding:const EdgeInsets.symmetric(horizontal:8,vertical:2),title:Text(entry.itemName,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Item: ${entry.itemName}'),if(entry.sizes.trim().isNotEmpty)Text('Size: ${entry.sizes}'),Text('Pieces: ${entry.pieces}'),Text('$dayName, ${entry.workDate}')]),trailing:SizedBox(width:132,child:Row(mainAxisAlignment:MainAxisAlignment.end,children:[Flexible(child:Text('Rs ${entry.total.toStringAsFixed(0)}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17,color:Colors.green),overflow:TextOverflow.ellipsis)),const SizedBox(width:2),IconButton(padding:EdgeInsets.zero,constraints:const BoxConstraints(minWidth:36,minHeight:36),tooltip:'Edit',icon:icon3D(context,Icons.edit,size:22,color:Colors.blue),onPressed:()async{final r=await Navigator.push(context,MaterialPageRoute(builder:(_)=>WorkPage(entry:entry)));if(r==true&&mounted)setState(refreshEntries);}),IconButton(padding:EdgeInsets.zero,constraints:const BoxConstraints(minWidth:36,minHeight:36),tooltip:'Delete',icon:icon3D(context,Icons.delete_forever,size:23,color:Colors.red),onPressed:()=>confirmDelete(entry))])))));}))]);}));}
 @override void dispose(){searchController.dispose();super.dispose();}
}
